INSERT INTO public.subscription_plans (id, name, tier, price_monthly, price_quarterly, price_yearly, currency, features, max_temple_listings, max_service_listings, max_photos, is_popular, display_order, is_active, created_at, updated_at, description, tagline, lead_credits_monthly) VALUES ('5b299d50-802e-4006-9f3f-0a2044546173', 'International leads ', 'diamond', 15000.00, 45000.00, 130000.00, 'INR', '["Premium International Visibility", "International User Lead Eligibility", "Priority Profile Placement", "Higher Search & Discovery Exposure", "Verified Pandit Badge", "Featured Profile Visibility", "Priority Listing in Eligible Searches", "Temple & Service Based Discovery", "Puja & Havan Service Visibility", "Online Puja Visibility", "Complete Pandit Profile", "Profile Photo & Gallery", "Video Introduction on Profile", "Services & Specializations Display", "Temple Association Display", "Languages & Experience Display", "Call & WhatsApp Lead Access", "Lead Analytics Dashboard", "Daily, Weekly & Monthly Lead Insights", "Profile Performance Analytics", "AI Recommender Eligibility", "AI-Based Pandit Discovery", "International Search Visibility", "Priority Support"]', 1, 5, 5, false, 0, true, '2026-08-21 10:12:32.533351+00', '2026-08-21 10:12:32.533351+00', 'Built for Pandits who want to expand their reach beyond India. The Diamond Plan provides premium visibility to international users searching for trusted Pandits for Puja, Havan, Anushthan, online rituals, and temple services. Get priority exposure across eligible international searches while remaining part of PanditSuggest’s fair lead distribution system.', 'Premium International Lead Plan', 20) ON CONFLICT DO NOTHING;
