-- ============================================================================
-- PanditSuggest — production configuration (T=0)
-- ============================================================================
-- Applied ONCE, immediately after baseline/0000-production-baseline.sql, by
-- scripts/migrate.js. Recorded in schema_migrations as version 0001.
--
-- SCOPE RULE: system and reference configuration ONLY — rows the application
-- cannot function without on an empty database. No users, no pandits, no
-- temples, no leads, no payments, no reviews, no analytics, no demo content.
-- Nothing here originates from historical/02-seed.sql's fixture accounts.
--
-- Values are carried forward from the live tuned configuration, not from the
-- migration defaults, because the distribution weights and page size below are
-- deliberate business decisions made by the super-admin (see the per-table
-- notes). Every updated_by/created_by has been set to NULL: those referenced
-- the legacy super-admin's user id, which does not exist in clean production.
--
-- Idempotent: every statement is ON CONFLICT DO NOTHING, so a re-run is a
-- no-op rather than a duplicate-key failure.
--
-- No BEGIN/COMMIT here on purpose: scripts/migrate.js wraps each migration in
-- one transaction together with its schema_migrations row, so that the change
-- and the record of it commit together. A file that manages its own
-- transaction would break that guarantee.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- subscription_plans  (2 rows)
-- ----------------------------------------------------------------------------
-- Sellable plans. Without a row here POST /pandits/:id/subscribe cannot
-- resolve a plan and no pandit can ever be sold anything.
-- Values carried forward from the live tuned configuration.

-- ----------------------------------------------------------------------------
-- plan_market_entitlements  (4 rows)
-- ----------------------------------------------------------------------------
-- Which tier may receive leads from which market, with its seat cap,
-- daily cap and allocation weight. record_qualified_lead() and the
-- distribution engine read this on EVERY lead; an empty table means no
-- pandit is eligible for any lead. NOTE: tier 'free' is deliberately
-- absent — free pandits are structurally excluded from paid distribution.
-- INDIA weights reflect the admin's 2026-08-30 rebalance (silver/gold 0.5/0.5).

-- ----------------------------------------------------------------------------
-- distribution_config  (14 rows)
-- ----------------------------------------------------------------------------
-- The 14 tuning keys the fairness/rotation engine reads per request.
-- Missing keys fall back to code defaults silently, which is exactly the
-- drift this table exists to prevent. Carries the admin's live tuning:
-- page_size=40 and pool_mode=2 (blended), not the migration defaults.

-- ----------------------------------------------------------------------------
-- ai_ranking_config  (15 rows)
-- ----------------------------------------------------------------------------
-- 15 retrieval/ranking weights for the AI recommender. Absent, the
-- assistant falls back to unweighted scoring and recommends poorly.

-- ----------------------------------------------------------------------------
-- ai_problem_categories  (43 rows)
-- ----------------------------------------------------------------------------
-- 43-row problem taxonomy the assistant maps a user's question onto.
-- Reference data, not user content. 30 rows carry parent_id, so the
-- insertion order below is load-bearing.

-- ----------------------------------------------------------------------------
-- service_categories  (4 rows)
-- ----------------------------------------------------------------------------
-- The 4 top-level catalogue categories (life, daily, shanti, festival).
-- Every service hangs off one of these.

-- ----------------------------------------------------------------------------
-- services  (32 rows)
-- ----------------------------------------------------------------------------
-- The 32-puja service catalogue — Griha Pravesh, Annaprashan, Antim
-- Sanskar and so on. This is genuine reference data describing real
-- rituals, not demo content: with an empty table the directory has
-- nothing to browse and a pandit cannot declare what they perform.

-- ----------------------------------------------------------------------------
-- ai_problem_service_mappings  (22 rows)
-- ----------------------------------------------------------------------------
-- 22 problem -> service links that turn a user's stated problem into a
-- concrete recommendation. temple_id is NULL in every row, so this does
-- not depend on any temple existing.
-- ----------------------------------------------------------------------------
-- Self-check
-- ----------------------------------------------------------------------------
DO $verify$
DECLARE n INT;
BEGIN
  SELECT count(*) INTO n FROM public.subscription_plans;
    IF n < 2  THEN RAISE EXCEPTION 'config 0001: expected >= 2 subscription_plans, found %', n; END IF;
  SELECT count(*) INTO n FROM public.plan_market_entitlements WHERE is_active;
    IF n < 4  THEN RAISE EXCEPTION 'config 0001: expected >= 4 active plan_market_entitlements, found %', n; END IF;
  SELECT count(*) INTO n FROM public.distribution_config;
    IF n < 14 THEN RAISE EXCEPTION 'config 0001: expected >= 14 distribution_config keys, found %', n; END IF;
  SELECT count(*) INTO n FROM public.ai_ranking_config;
    IF n < 15 THEN RAISE EXCEPTION 'config 0001: expected >= 15 ai_ranking_config keys, found %', n; END IF;
  SELECT count(*) INTO n FROM public.services;
    IF n < 32 THEN RAISE EXCEPTION 'config 0001: expected >= 32 services, found %', n; END IF;

  -- The whole point of this file: configuration, never business data.
  SELECT count(*) INTO n FROM public.users;    IF n > 0 THEN RAISE EXCEPTION 'config 0001 must not create users (found %)', n; END IF;
  SELECT count(*) INTO n FROM public.pandits;  IF n > 0 THEN RAISE EXCEPTION 'config 0001 must not create pandits (found %)', n; END IF;
  SELECT count(*) INTO n FROM public.temples;  IF n > 0 THEN RAISE EXCEPTION 'config 0001 must not create temples (found %)', n; END IF;

  RAISE NOTICE 'config 0001 applied: plans, entitlements, distribution + AI tuning and the % service catalogue.', (SELECT count(*) FROM public.services);
END
$verify$;
